import { readFile } from "node:fs/promises";
import { join } from "node:path";
import glyphData from "./glyphs.json";

/*
 * Shared pieces for the social preview images (app/opengraph-image.tsx and
 * app/work/[slug]/opengraph-image.tsx). Both are rendered once at build time.
 *
 * The image renderer (Satori, inside next/og) cannot draw outlined text or
 * read variable fonts, so display type is drawn from the headline font's
 * glyph outlines (lib/og/glyphs.json, generated by
 * scripts/build-brand-assets.py) as SVG paths. That keeps the letterforms,
 * kerning and outline style identical to the site.
 */

export const OG_SIZE = { width: 1200, height: 630 };

export const og = {
  canvas: "#FDFDFD",
  surface: "#F4F2F0",
  line: "#E6E3E0",
  ink: "#0A0909",
  inkSoft: "#4A4645",
  inkMuted: "#A3A09D",
  inkLine: "#2A2726",
  muted: "#707070",
  accent: "#9C6455",
  status: "#22C55E",
};

type GlyphData = {
  unitsPerEm: number;
  capHeight: number;
  glyphs: Record<string, { a: number; d: string }>;
  kern: Record<string, number>;
};
const font = glyphData as GlyphData;

/** Width in font units of a string set in the headline font, with kerning. */
function measure(text: string): number {
  let x = 0;
  let prev = "";
  for (const ch of text) {
    const g = font.glyphs[ch] ?? font.glyphs[" "];
    if (prev) x += font.kern[prev + ch] ?? 0;
    x += g.a;
    prev = ch;
  }
  return x;
}

/** Font size (px) at which the widest line fills `width`, capped at `max`. */
export function fitSize(lines: string[], width: number, max: number): number {
  const widest = Math.max(...lines.map((l) => measure(l.toUpperCase())));
  return Math.min(max, Math.floor((width / widest) * font.unitsPerEm));
}

type DisplayProps = {
  text: string;
  /** Font size in px (the em square, as in CSS). */
  size: number;
  color: string;
  /** Draw only the outline, like .text-outline on the site. */
  outline?: boolean;
  /** Outline thickness in px. */
  stroke?: number;
};

/**
 * One line of uppercase display type as an SVG image. The box is sized to the
 * cap height (plus room for the outline), so lines stack tightly like the
 * site's 0.86 line height without extra space above the capitals.
 */
export function Display({ text, size, color, outline = false, stroke = 2.5 }: DisplayProps) {
  const upper = text.toUpperCase();
  const scale = size / font.unitsPerEm;
  const pad = outline ? stroke / scale : 0;
  let x = 0;
  let prev = "";
  const paths: string[] = [];
  for (const ch of upper) {
    const g = font.glyphs[ch] ?? font.glyphs[" "];
    if (prev) x += font.kern[prev + ch] ?? 0;
    if (g.d) paths.push(`<path transform="translate(${x} 0)" d="${g.d}"/>`);
    x += g.a;
    prev = ch;
  }
  const top = -font.capHeight - pad;
  const w = x + pad * 2;
  const h = font.capHeight + pad * 2;
  const paint = outline
    ? `fill="none" stroke="${color}" stroke-width="${stroke / scale}" stroke-linejoin="round"`
    : `fill="${color}"`;
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${-pad} ${top} ${w} ${h}">` +
    `<g ${paint}>${paths.join("")}</g></svg>`;
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      alt=""
      src={`data:image/svg+xml;base64,${Buffer.from(svg).toString("base64")}`}
      width={Math.ceil(w * scale)}
      height={Math.ceil(h * scale)}
    />
  );
}

/** The site's availability pill, drawn for the image. */
export function StatusPill({ dark = false }: { dark?: boolean }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 10,
        padding: "10px 18px",
        borderRadius: 999,
        border: `1.5px solid ${dark ? og.inkLine : og.line}`,
        color: dark ? og.canvas : og.ink,
        fontSize: 20,
      }}
    >
      <div style={{ width: 10, height: 10, borderRadius: 999, background: og.status }} />
      Open to opportunities
    </div>
  );
}

const root = process.cwd();

/** Fonts for small text in the images. Read once per build worker. */
let fontsPromise: Promise<{ name: string; data: Buffer; weight: 500; style: "normal" }[]> | null = null;
export function ogFonts() {
  fontsPromise ??= readFile(join(root, "lib/og/Inter-Medium.ttf")).then((data) => [
    { name: "Inter", data, weight: 500 as const, style: "normal" as const },
  ]);
  return fontsPromise;
}

/** The grayscale hero cutout as a data URL, with its pixel size. */
export async function ogPortrait() {
  const data = await readFile(join(root, "lib/og/portrait.png"));
  return { src: `data:image/png;base64,${data.toString("base64")}`, width: 624, height: 760 };
}
